import type { CollectorEnv } from '../src/schema';
import { DC_MAX_RESPONSE_BYTES } from '../src/research/dc-contract';
import { dcResearchConfigs } from '../src/research/dc-sources';
import { fetchDCTrackerPage } from '../src/research/dc-network';
import { collectResearchPage } from '../src/research/pipeline';
import { dcSizeBody, dcSizeCases, dcSizeMarker } from './dc-size-helpers';

// Real workerd parsing/hashing/D1/R2, generated bytes and injected HTTP only.
export async function dcSizeRuntime(env: CollectorEnv) {
  const at = '2026-11-09T18:17:00.000Z';
  const sources = [];
  for (const sample of dcSizeCases) {
    const config = dcResearchConfigs.find((c) => c.source.source_id === sample.source)!;
    const body = dcSizeBody(DC_MAX_RESPONSE_BYTES, sample.type);
    let requests = 0;
    const result = await collectResearchPage(env, config, { kind: 'dc_tracker' }, at, {
      current_terms_version: config.terms.version,
      now: () => at,
      allow_network: true,
      fetcher: async (url) => {
        requests++;
        return String(url).endsWith('/robots.txt')
          ? new Response(null, { status: 404 })
          : new Response(body, { headers: { 'content-type': sample.type } });
      },
    });
    const evidence = await env.EVIDENCE.get(`research/${sample.source}/${result.run_id}/0.json`);
    const encoded = await evidence!.text();
    sources.push({
      source_id: sample.source,
      state: result.state,
      bytes: body.byteLength,
      requests,
      expected_requests: config.dc_access!.projects.length + 1,
      evidence_bytes: evidence!.size,
      retained_body: encoded.includes(dcSizeMarker),
      observations: (await env.PRIVATE_DB.prepare(
        'SELECT COUNT(*) n FROM dc_observations WHERE run_id=?',
      )
        .bind(result.run_id)
        .first<{ n: number }>())!.n,
    });
  }
  const malformed = '<title '
    .repeat(Math.ceil(DC_MAX_RESPONSE_BYTES / 7))
    .slice(0, DC_MAX_RESPONSE_BYTES);
  const result = await fetchDCTrackerPage(dcResearchConfigs[0], {
    now: () => at,
    fetcher: async (url) =>
      String(url).endsWith('/robots.txt')
        ? new Response(null, { status: 404 })
        : new Response(malformed, { headers: { 'content-type': 'text/html' } }),
  });
  return Response.json({
    sources,
    malformed_title: JSON.parse(result.text).records[0].value_text,
    external_http_requests: 0,
  });
}
